class Solution {
  public long countRatioSubarrays(int[] nums, int a, int b) {
    int n = nums.length;
    long[] prefix = new long[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + (nums[i] % 2 == 0 ? b : -(long) a);
    long[] sorted = prefix.clone();
    java.util.Arrays.sort(sorted);
    int m = 0;
    for (int i = 0; i <= n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
    long[] bit = new long[m + 2];
    long total = 0;
    for (int i = 0; i <= n; i++) {
      int rank = java.util.Arrays.binarySearch(sorted, 0, m, prefix[i]) + 1;
      // earlier prefixes with value >= current: prefix[i] - earlier <= 0
      long ge = i - query(bit, rank - 1);
      total += ge;
      for (int p = rank; p <= m; p += p & -p) bit[p]++;
    }
    return total;
  }

  private static long query(long[] bit, int i) {
    long s = 0;
    for (; i > 0; i -= i & -i) s += bit[i];
    return s;
  }
}
